static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) void
anon_vma_name_get(struct anon_vma_name *anon_name)
{
	if (anon_name)
		kref_get(&anon_name->kref);
}

static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) void
anon_vma_name_put(struct anon_vma_name *anon_name)
{
	if (anon_name)
		kref_put(&anon_name->kref, anon_vma_name_free);
}

static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) struct anon_vma_name *
anon_vma_name_reuse(struct anon_vma_name *anon_name)
{
	if (kref_read(&anon_name->kref) < ((int)(~0U >> 1))) {
		anon_vma_name_get(anon_name);
		return anon_name;
	}
	return anon_vma_name_alloc(anon_name->name);
}

static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) void
dup_anon_vma_name(struct vm_area_struct *orig_vma,
		  struct vm_area_struct *new_vma)
{
	struct anon_vma_name *anon_name = anon_vma_name(orig_vma);

	if (anon_name)
		new_vma->anon_name = anon_vma_name_reuse(anon_name);
}

static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) void
free_anon_vma_name(struct vm_area_struct *vma)
{
	anon_vma_name_put(vma->anon_name);
}

static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) bool
anon_vma_name_eq(struct anon_vma_name *anon_name1,
		 struct anon_vma_name *anon_name2)
{
	if (anon_name1 == anon_name2)
		return true;

	return anon_name1 && anon_name2 &&
	       !strcmp(anon_name1->name, anon_name2->name);
}
